import sys, json, os, random, subprocess, copy
from fractions import Fraction
sys.path.insert(0,'/app/tmp'); sys.path.insert(0,'/app/submit')
from t_common import *
import scamp_pipeline as sp

rng = random.Random(int(sys.argv[1]) if len(sys.argv)>1 else 1)

base_compile = {'op':'compile','fib':[{'prefix':'::/0','hop':7},{'prefix':'2001:db8::/32','hop':8},
                                      {'prefix':'2001:db8::1/128','hop':9},{'prefix':'2001:db9::/48','hop':3}],
                'capacities':[4096,4096,4096,4096],'max_stride':32}
img = json.load(open('/app/examples/sample.image.json'))
base_lookup = {'op':'lookup','image':img,'addresses':['2001:db8::1','::1','::','ffff::']}

JUNK = [None, True, False, 0, -1, 1.5, '', 'x', [], {}, [1], {'a':1}, 10**20, '::/0', 65536]

def mutate(obj, depth=0):
    o = copy.deepcopy(obj)
    for _ in range(rng.randint(1,3)):
        path = []
        cur = o
        while isinstance(cur, dict) and len(path) < 6:
            k = rng.choice(list(cur.keys()))
            path.append(k)
            cur = cur[k]
            if isinstance(cur, list) and cur and rng.random()<0.7:
                i = rng.randrange(len(cur)); path.append(i); cur = cur[i]
                if rng.random()<0.3 and isinstance(cur,dict):
                    k = rng.choice(list(cur.keys())); path.append(k); cur = cur[k]
            if rng.random()<0.5: break
        # apply
        t = rng.random()
        target = o
        try:
            for p in path[:-1]:
                target = target[p]
            last = path[-1]
            if t < 0.3:
                target[last] = rng.choice(JUNK)
            elif t < 0.5:
                if isinstance(target[last], int) and not isinstance(target[last], bool):
                    target[last] = target[last] + rng.choice([-2,-1,1,2,32,64,128,-128])
                else:
                    target[last] = rng.choice(JUNK)
            elif t < 0.65:
                if isinstance(target, dict): del target[last]
            elif t < 0.8:
                if isinstance(target, dict): target['zz_' + str(rng.randint(0,3))] = rng.choice(JUNK)
            elif t < 0.9:
                if isinstance(target, list):
                    if target: del target[rng.randrange(len(target))]
                elif isinstance(target, dict):
                    target[last] = copy.deepcopy(target[last])
            else:
                if isinstance(target, list): target.append(rng.choice(JUNK))
        except Exception:
            pass
    return o

def byte_mut(s):
    b = bytearray(s)
    for _ in range(rng.randint(1,4)):
        if not b: break
        i = rng.randrange(len(b))
        t = rng.random()
        if t < 0.4: b[i] = rng.randrange(256)
        elif t < 0.7: del b[i]
        else: b.insert(i, rng.choice(b'{}[]",:0123456789.eE-+ \n\t\\/ab'))
    if rng.random() < 0.2 and len(b) > 5:
        b = b[:rng.randrange(1, len(b))]
    return bytes(b).replace(b'\n', b' ')

lines = []
kinds = []
for t in range(700):
    base = base_compile if rng.random()<0.5 else base_lookup
    m = mutate(base)
    s = json.dumps(m, separators=(',',':'), allow_nan=False)
    if rng.random()<0.25:
        s = byte_mut(s.encode()).decode('utf-8','replace')
    s = s.replace('\n',' ')
    lines.append(s)
    kinds.append(m)

inp = ''.join(l+'\n' for l in lines)
p = subprocess.run(['/app/submit/run'], input=inp.encode('utf-8','replace'), capture_output=True, timeout=900)
assert p.returncode == 0, (p.returncode, p.stderr[:2000])
out = p.stdout.split(b'\n')
assert out[-1] == b'', repr(out[-1][:100])
out = out[:-1]
assert len(out) == len(lines), (len(out), len(lines))
counts = {}
for i, o in enumerate(out):
    try:
        r = json.loads(o)
    except Exception:
        print('NON-JSON response', i, o[:200], 'input', lines[i][:200]); raise SystemExit(1)
    st = r.get('status')
    counts[st] = counts.get(st,0)+1
    assert set(r.keys()) >= {'status'}, r
    if st == 'invalid':
        assert r == {'status':'invalid'}, r
    elif st == 'infeasible':
        assert r == {'status':'infeasible'}, r
    elif st == 'ok':
        if 'answers' in r:
            assert set(r.keys()) == {'status','answers'}, r
            for a in r['answers']:
                assert set(a.keys()) == {'hop','prefix_length'}, a
                assert (a['hop'] is None) == (a['prefix_length'] is None), a
                if a['hop'] is not None:
                    assert isinstance(a['hop'], int) and 0 <= a['hop'] <= 65535
                    assert isinstance(a['prefix_length'], int) and 0 <= a['prefix_length'] <= 128
        else:
            assert set(r.keys()) == {'status','capacities','max_stride','cuts','stages','used_bits','peak'}, r
print('fuzz responses:', counts, 'stderr:', p.stderr[:200])
print('FUZZ1 OK')
EOF
